function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const top = 1000000;
  if (size === 'small') {
    // Short arrays mixing climbs by 1, repeats, drops, jumps and values at the upper limit.
    const n = int(1, 9);
    const nearTop = rand() < 0.2;
    const nums = [];
    for (let i = 0; i < n; i++) {
      const roll = rand();
      if (i > 0 && roll < 0.55 && nums[i - 1] < top) nums.push(nums[i - 1] + 1);
      else if (i > 0 && roll < 0.65) nums.push(nums[i - 1]);
      else nums.push(nearTop ? int(top - 4, top) : int(1, 8));
    }
    return [nums, int(1, n)];
  }
  // Large arrays are built from climbing runs, short ones for a small k or long ones for a large k.
  const n = 2000;
  const longRuns = rand() < 0.5;
  const nums = [];
  while (nums.length < n) {
    const length = longRuns ? int(1, 700) : int(1, 25);
    let value = int(1, top - length);
    for (let j = 0; j < length && nums.length < n; j++) nums.push(value++);
  }
  const k = longRuns ? int(100, 600) : int(1, 20);
  return [nums, k];
}
